CREATE TABLE roles (id text PRIMARY KEY NOT NULL, code text NOT NULL UNIQUE, name text NOT NULL, created_at integer NOT NULL, updated_at integer NOT NULL);
CREATE TABLE airports (id text PRIMARY KEY NOT NULL, code text NOT NULL UNIQUE, name text NOT NULL, active integer DEFAULT true NOT NULL, created_at integer NOT NULL, updated_at integer NOT NULL);
CREATE TABLE users (id text PRIMARY KEY NOT NULL, email text NOT NULL UNIQUE, display_name text NOT NULL, role_id text REFERENCES roles(id), airport_id text REFERENCES airports(id), active integer DEFAULT true NOT NULL, created_at integer NOT NULL, updated_at integer NOT NULL);
CREATE TABLE units (id text PRIMARY KEY NOT NULL, airport_id text NOT NULL REFERENCES airports(id), name text NOT NULL, created_at integer NOT NULL, updated_at integer NOT NULL);
CREATE TABLE report_types (id text PRIMARY KEY NOT NULL, code text NOT NULL UNIQUE, name text NOT NULL, active integer DEFAULT true NOT NULL, created_at integer NOT NULL, updated_at integer NOT NULL);
CREATE TABLE report_templates (id text PRIMARY KEY NOT NULL, report_type_id text NOT NULL REFERENCES report_types(id), version integer NOT NULL, subject_pattern text NOT NULL, template_body text NOT NULL, required_fields text NOT NULL, validation_rules text, status text NOT NULL, created_at integer NOT NULL, updated_at integer NOT NULL);
CREATE UNIQUE INDEX template_version_idx ON report_templates (report_type_id, version);
CREATE TABLE form_fields (id text PRIMARY KEY NOT NULL, report_type_id text NOT NULL REFERENCES report_types(id), field_key text NOT NULL, label text NOT NULL, type text NOT NULL, required integer DEFAULT false NOT NULL, options text, sort_order integer NOT NULL, created_at integer NOT NULL, updated_at integer NOT NULL);
CREATE TABLE incidents (id text PRIMARY KEY NOT NULL, incident_number text NOT NULL UNIQUE, airport_id text NOT NULL REFERENCES airports(id), occurred_at integer, status text NOT NULL, created_at integer NOT NULL, updated_at integer NOT NULL);
CREATE TABLE reports (id text PRIMARY KEY NOT NULL, report_number text NOT NULL UNIQUE, incident_id text REFERENCES incidents(id), airport_id text NOT NULL REFERENCES airports(id), unit_id text REFERENCES units(id), report_type_id text NOT NULL REFERENCES report_types(id), template_id text REFERENCES report_templates(id), report_date text NOT NULL, status text NOT NULL, structured_data text NOT NULL, generated_content text, submitted_by text REFERENCES users(id), finalized_at integer, created_at integer NOT NULL, updated_at integer NOT NULL);
CREATE INDEX report_date_idx ON reports (report_date); CREATE INDEX report_status_idx ON reports (status);
CREATE TABLE report_messages (id text PRIMARY KEY NOT NULL, report_id text NOT NULL REFERENCES reports(id), source_text text NOT NULL, received_at integer, source_ref text, created_at integer NOT NULL, updated_at integer NOT NULL);
CREATE TABLE report_versions (id text PRIMARY KEY NOT NULL, report_id text NOT NULL REFERENCES reports(id), version_number integer NOT NULL, content text NOT NULL, structured_data text NOT NULL, changed_by text REFERENCES users(id), change_type text NOT NULL, change_reason text, created_at integer NOT NULL);
CREATE TABLE report_reviews (id text PRIMARY KEY NOT NULL, report_id text NOT NULL REFERENCES reports(id), reviewer_id text NOT NULL REFERENCES users(id), action text NOT NULL, comments text, created_at integer NOT NULL);
CREATE TABLE audit_logs (id text PRIMARY KEY NOT NULL, actor_id text REFERENCES users(id), entity_type text NOT NULL, entity_id text NOT NULL, action text NOT NULL, metadata text, created_at integer NOT NULL);
CREATE TABLE attachments (id text PRIMARY KEY NOT NULL, report_id text NOT NULL REFERENCES reports(id), file_name text NOT NULL, content_type text NOT NULL, storage_key text NOT NULL, uploaded_by text REFERENCES users(id), created_at integer NOT NULL, updated_at integer NOT NULL);
CREATE TABLE passengers (id text PRIMARY KEY NOT NULL, report_id text NOT NULL REFERENCES reports(id), name text NOT NULL, father_name text, passport_number text, cnic text, nationality text, created_at integer NOT NULL, updated_at integer NOT NULL);
CREATE TABLE vehicles (id text PRIMARY KEY NOT NULL, report_id text NOT NULL REFERENCES reports(id), registration text NOT NULL, vehicle_type text, created_at integer NOT NULL, updated_at integer NOT NULL);
CREATE TABLE recoveries (id text PRIMARY KEY NOT NULL, report_id text NOT NULL REFERENCES reports(id), item text NOT NULL, quantity integer NOT NULL, unit text, disposition text, created_at integer NOT NULL, updated_at integer NOT NULL);
CREATE TABLE staff_members (id text PRIMARY KEY NOT NULL, report_id text NOT NULL REFERENCES reports(id), service_number text, name text NOT NULL, role text, created_at integer NOT NULL, updated_at integer NOT NULL);
